var combinedPolicy = Policy
    .WrapAsync(new[]
    {
        // 1. Circuit breaker first
        Policy
            .Handle<HttpRequestException>()
            .CircuitBreakerAsync(
                handledEventsAllowedBeforeBreaking: 5,
                durationOfBreak: TimeSpan.FromSeconds(30)),
        // 2. Retry with exponential backoff
        Policy
            .Handle<HttpRequestException>()
            .WaitAndRetryAsync(
                retryCount: 3,
                sleepDurationProvider: attempt => 
                    TimeSpan.FromSeconds(Math.Pow(2, attempt))),
        // 3. Timeout as the outermost policy
        Policy.TimeoutAsync(TimeSpan.FromSeconds(5))
    });

var result = await combinedPolicy.ExecuteAsync(
    async () => await httpClient.GetAsync("https://api.example.com"));
